		}
		dx := old.X - oldAnchor.X
		dy := old.Y - oldAnchor.Y
		np := Pose{
			Time:     old.Time,
			X:        tgt.X + cosH*dx - sinH*dy,
			Y:        tgt.Y + sinH*dx + cosH*dy,
			Heading:  normalizeAngle(old.Heading + dHeading),
