	// 重放，完整复刻导入时的增量平均与合并距离判定。
	type agg struct {
		count int
		x, y  float64
	}
	aggs := make(map[string]*agg, len(affectedIDs))
	for _, id := range affectedIDs {
		lm := st.landmarks[id]
		a := &agg{}
		if lm != nil && lm.legacyCount > 0 {
			a.count = lm.legacyCount
			a.x = lm.legacyMX
			a.y = lm.legacyMY
		}
		aggs[id] = a
