15	// 之后至该帧的原运动方差累计值。更早的位姿不变。
16	//
17	// 受影响帧中的路标观测随新位姿改变地图位置；更早观测的地图位置不变。
18	// 同一路标仍按全部已接受观测、依原时间与同帧输入次序做增量平均并遵守
19	// 合并距离限制；观测次数不变。若校正后出现路标冲突，整次校正拒绝并说
20	// 明冲突帧时间与路标。输入或校正结果含非有限数值同样拒绝。
21	//
22	// 同一标识以相同内容重复提交返回首次结果且不再修改数据；同一标识不同
23	// 内容明确拒绝。任何拒绝或保存失败都不改变轨迹、路标与既有校正记录。
24	// 旧文件缺少逐帧观测来源时，覆盖其历史范围的校正返回 RejectNoBasis。
25	func (m *Map) Correct(req Correction) (CorrectionRecord, error) {
26		m.mu.Lock()
27		defer m.mu.Unlock()
28		if m.closed {
29			return CorrectionRecord{}, ErrClosed
30		}
31		st := m.state
32	
33		// 已保存校正：相同内容直接返回首次记录；不同内容明确拒绝。
34		if hash, ok := st.corrIndex[req.ID]; ok {
35			if req.ID != "" && hash == canonicalCorrectionHash(req.Anchor, req.Target) {
36				return cloneRecord(st.correctionRecordByID(req.ID)), nil
37			}
38			return CorrectionRecord{}, &RejectError{Kind: RejectCorrectionMismatch, Landmark: req.ID, HasLandmark: true}
39		}
40	
41		if req.ID == "" {
42			return CorrectionRecord{}, &RejectError{Kind: RejectEmptyID}
43		}
44		tgt := req.Target
45		if !isFinite(tgt.X) || !isFinite(tgt.Y) || !isFinite(tgt.Heading) || !isFinite(tgt.Variance) {
46			return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
47		}
48		if tgt.Variance < 0 {
49			return CorrectionRecord{}, &RejectError{Kind: RejectNegativeVariance, Time: req.Anchor, HasTime: true}
50		}
51	
52		// 锚点必须准确命中已导入帧：trajectory[0] 是初始位姿，不能校正。
53		anchorIdx := -1
54		for j := 1; j < len(st.trajectory); j++ {
55			if st.trajectory[j].Time == req.Anchor {
56				anchorIdx = j
57				break
58			}
59		}
60		if anchorIdx < 0 {
61			return CorrectionRecord{}, &RejectError{Kind: RejectAnchorNotFound, Time: req.Anchor, HasTime: true}
62		}
63		end := len(st.trajectory) - 1
64	
65		// 受影响范围内每一帧都必须有逐帧依据（旧文件没有，不能靠推测校正）。
66		for k := anchorIdx - 1; k < len(st.sources); k++ {
67			if st.sources[k] == nil {
68				return CorrectionRecord{}, &RejectError{Kind: RejectNoBasis, Time: req.Anchor, HasTime: true}
69			}
70		}
71	
72		oldAnchor := st.trajectory[anchorIdx]
73		newHeading := normalizeAngle(tgt.Heading)
74		// 相对位姿整体旋转 δ；平移锚点到目标位置。
75		dHeading := normalizeAngle(newHeading - oldAnchor.Heading)
76		cosD, sinD := math.Cos(dHeading), math.Sin(dHeading)
77	
78		// ---- 在副本上推演新位姿，真实状态此时保持不变 ----
79		next := append([]Pose(nil), st.trajectory...)
80		accumVar := tgt.Variance
81		for j := anchorIdx; j <= end; j++ {
82			old := st.trajectory[j]
83			if j > anchorIdx {
84				accumVar += st.sources[j-1].moveVariance
85			}
86			dx := old.X - oldAnchor.X
87			dy := old.Y - oldAnchor.Y
88			np := Pose{
89				Time:     old.Time,
90				X:        tgt.X + cosD*dx - sinD*dy,
91				Y:        tgt.Y + sinD*dx + cosD*dy,
92				Heading:  normalizeAngle(old.Heading + dHeading),
93				Variance: accumVar,
94			}
95			if !isFinite(np.X) || !isFinite(np.Y) || !isFinite(np.Heading) || !isFinite(np.Variance) {
96				return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
97			}
98			next[j] = np
99		}
100	
101		// 受影响路标：在受影响帧中被观测到的全部路标。
102		affected := make(map[string]struct{})
103		for j := anchorIdx; j <= end; j++ {
104			for _, ob := range st.sources[j-1].observations {
105				affected[ob.ID] = struct{}{}
106			}
107		}
108		affectedIDs := make([]string, 0, len(affected))
109		for id := range affected {
110			affectedIDs = append(affectedIDs, id)
111		}
112		sort.Strings(affectedIDs)
113	
114		// 逐路标运行聚合：旧文件的既有观测作为固定“旧贡献”起点（位置不
115		// 随校正改变），其余观测按帧时间与同帧输入次序、以当前/校正后位姿
116		// 重放，完整复刻导入时的增量平均与合并距离判定。
117		type agg struct {
118			count int
119			x, y  float64
120		}
121		aggs := make(map[string]*agg, len(affectedIDs))
122		for _, id := range affectedIDs {
123			lm := st.landmarks[id]
124			a := &agg{}
125			if lm != nil && lm.legacyCount > 0 {
126				a.count = lm.legacyCount
127				a.x = lm.legacyMX
128				a.y = lm.legacyMY
129			}
130			aggs[id] = a
131		}
132		for j := 1; j <= end; j++ {
133			src := st.sources[j-1]
134			if src == nil {
135				continue // 旧文件帧：观测已计入各路标 legacy 起点
136			}
137			pose := next[j]
138			for _, ob := range src.observations {
139				a, ok := aggs[ob.ID]
140				if !ok {
141					continue
142				}
143				mx, my := localToMap(pose.X, pose.Y, pose.Heading, ob.X, ob.Y)
144				if a.count > 0 && math.Hypot(mx-a.x, my-a.y) > st.config.MergeDistance {
145					return CorrectionRecord{}, &RejectError{
146						Kind:        RejectLandmarkConflict,
147						Time:        st.trajectory[j].Time,
148						HasTime:     true,
149						Landmark:    ob.ID,
150						HasLandmark: true,
151					}
152				}
153				a.x = (a.x*float64(a.count) + mx) / float64(a.count+1)
154				a.y = (a.y*float64(a.count) + my) / float64(a.count+1)
155				a.count++
156			}
157		}
158		for id, a := range aggs {
159			if !isFinite(a.x) || !isFinite(a.y) {
160				return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
161			}
162			if lm := st.landmarks[id]; lm == nil || a.count != lm.count {
163				// 内存不变量被破坏不可能由本包写出，按损坏处理而非半提交。
164				return CorrectionRecord{}, ErrCorrupt
165			}
166		}
167	
168		// ---- 组装校正前后快照（记录不可变） ----
169		rec := &CorrectionRecord{
170			ID:        req.ID,
171			Anchor:    req.Anchor,
172			Target:    tgt,
173			EndTime:   st.trajectory[end].Time,
174			Poses:     make([]PoseChange, 0, end-anchorIdx+1),
175			Landmarks: make([]LandmarkChange, 0, len(affectedIDs)),
176		}
177		for j := anchorIdx; j <= end; j++ {
178			rec.Poses = append(rec.Poses, PoseChange{Before: st.trajectory[j], After: next[j]})
179		}
180		for _, id := range affectedIDs {
181			lm := st.landmarks[id]
182			a := aggs[id]
183			rec.Landmarks = append(rec.Landmarks, LandmarkChange{
184				ID:     id,
185				Before: Landmark{ID: id, X: lm.x, Y: lm.y, Count: lm.count},
186				After:  Landmark{ID: id, X: a.x, Y: a.y, Count: a.count},
187			})
188		}
189	
190		// ---- 全部校验通过：暂存提交并落盘；落盘失败精确回滚 ----
191		oldTraj := append([]Pose(nil), st.trajectory...)
192		type lmSnapshot struct {
193			x, y               float64
194			count, legacyCount int
195			legacyMX, legacyMY float64
196		}
197		oldLM := make(map[string]lmSnapshot, len(affectedIDs))
198		for _, id := range affectedIDs {
199			lm := st.landmarks[id]
200			oldLM[id] = lmSnapshot{lm.x, lm.y, lm.count, lm.legacyCount, lm.legacyMX, lm.legacyMY}
201		}
202		oldCorrLen := len(st.corrections)
203	
204		st.trajectory = next
205		for _, id := range affectedIDs {
206			a := aggs[id]
207			lm := st.landmarks[id]
208			lm.x, lm.y = a.x, a.y
209		}
210		st.corrections = append(st.corrections, rec)
211		st.corrIndex[req.ID] = canonicalCorrectionHash(req.Anchor, tgt)
212	
213		if err := m.saveReplace(); err != nil {
214			st.trajectory = oldTraj
215			for id, s := range oldLM {
216				lm := st.landmarks[id]
217				lm.x, lm.y, lm.count = s.x, s.y, s.count
218				lm.legacyCount, lm.legacyMX, lm.legacyMY = s.legacyCount, s.legacyMX, s.legacyMY
219			}
220			st.corrections = st.corrections[:oldCorrLen]
221			delete(st.corrIndex, req.ID)
222			return CorrectionRecord{}, err
223		}
224		return cloneRecord(rec), nil
225	}
226	
227	// Corrections 返回按提交次序排列的成功校正记录副本。记录一经生成永不
228	// 被后续校正改写；后续校正只是以当时最新状态为起点生成新记录。
229	func (m *Map) Corrections() ([]CorrectionRecord, error) {
230		m.mu.Lock()
231		defer m.mu.Unlock()
232		if m.closed {
233			return nil, ErrClosed
234		}
235		out := make([]CorrectionRecord, 0, len(m.state.corrections))
236		for _, rec := range m.state.corrections {
237			out = append(out, cloneRecord(rec))
238		}
239		return out, nil
240	}
241	
242	func (st *mapState) correctionRecordByID(id string) *CorrectionRecord {
243		for _, rec := range st.corrections {
244			if rec.ID == id {
245				return rec
246			}
247		}
248		return nil
249	}
250	
251	func cloneRecord(rec *CorrectionRecord) CorrectionRecord {
252		if rec == nil {
253			return CorrectionRecord{}
254		}
255		cp := *rec
256		cp.Poses = append([]PoseChange(nil), rec.Poses...)
257		cp.Landmarks = append([]LandmarkChange(nil), rec.Landmarks...)
258		return cp
259	}
